import React, { useState, useEffect } from 'react';
import { 
  Container, Row, Col, Card, Button, 
  Badge, Alert 
} from 'react-bootstrap';
import { Link, useNavigate } from 'react-router-dom';

const HomePage = () => {
  const navigate = useNavigate();
  const [backendStatus, setBackendStatus] = useState('checking');
  const [quickSearch, setQuickSearch] = useState({
    vendor: '',
    package: ''
  });

  // Check backend status
  useEffect(() => {
    const checkBackend = async () => {
      try {
        const response = await fetch('http://localhost:5000/health');
        if (response.ok) {
          setBackendStatus('connected');
        } else {
          setBackendStatus('error');
        }
      } catch (error) {
        console.error('Backend check error:', error);
        setBackendStatus('error');
      }
    };

    checkBackend();
  }, []);

  const handleQuickSearch = (type) => {
    const query = type === 'vendor' ? quickSearch.vendor : quickSearch.package;
    if (!query.trim()) {
      alert(`Masukkan ${type === 'vendor' ? 'nama vendor' : 'kata kunci'} terlebih dahulu`);
      return;
    }
    
    if (type === 'vendor') {
      navigate(`/vendor?q=${encodeURIComponent(query)}`);
    } else {
      navigate(`/package?q=${encodeURIComponent(query)}`);
    }
  };

  const handleDemoSearch = (type) => {
    const demoQueries = {
      vendor: 'Adhi Karya',
      package: 'jalan'
    };
    
    if (type === 'vendor') {
      setQuickSearch(prev => ({ ...prev, vendor: demoQueries.vendor }));
      setTimeout(() => navigate(`/vendor?q=${encodeURIComponent(demoQueries.vendor)}`), 100);
    } else {
      setQuickSearch(prev => ({ ...prev, package: demoQueries.package }));
      setTimeout(() => navigate(`/package?q=${encodeURIComponent(demoQueries.package)}`), 100);
    }
  };

  return (
    <Container className="py-5">
      {/* Hero Section */}
      <Row className="mb-5">
        <Col>
          <div className="text-center mb-5">
            <h1 className="display-4 fw-bold mb-3">
              <span className="text-primary">SPSE</span> Scraper v9.0
              <Badge bg="success" className="ms-3">2026 Ready</Badge>
            </h1>
            <p className="lead mb-4">
              Aplikasi pencarian paket tender dan rekanan SPSE terintegrasi. 
              Dukung tahun 2023-2026 dengan sistem autentikasi lengkap.
            </p>
            
            <div className="d-flex flex-wrap justify-content-center gap-3 mb-4">
              <Button 
                variant="primary" 
                size="lg"
                onClick={() => navigate('/vendor')}
              >
                <i className="fas fa-search me-2"></i>
                Cari Vendor
              </Button>
              <Button 
                variant="success" 
                size="lg"
                onClick={() => navigate('/package')}
              >
                <i className="fas fa-box me-2"></i>
                Cari Paket
              </Button>
              <Button 
                variant="info" 
                size="lg"
                onClick={() => navigate('/sbu')}
              >
                <i className="fas fa-certificate me-2"></i>
                SBU LPJK
              </Button>
            </div>
            
            {/* Backend Status */}
            <div className="mb-4">
              <Badge bg={backendStatus === 'connected' ? 'success' : 'danger'} className="p-3">
                <i className={`fas fa-${backendStatus === 'connected' ? 'check-circle' : 'exclamation-triangle'} me-2`}></i>
                Backend: {backendStatus === 'connected' ? 'Terhubung' : 'Terputus'}
              </Badge>
              {backendStatus === 'error' && (
                <Alert variant="danger" className="mt-3">
                  <i className="fas fa-exclamation-triangle me-2"></i>
                  Backend tidak terhubung. Pastikan Python backend berjalan di port 5000.
                </Alert>
              )}
            </div>
          </div>
        </Col>
      </Row>

      {/* Quick Search */}
      <Row className="mb-5">
        <Col>
          <Card className="shadow-sm mb-4">
            <Card.Body>
              <h4 className="mb-4">
                <i className="fas fa-bolt me-2 text-warning"></i>
                Pencarian Cepat
              </h4>
              
              <Row>
                <Col md={6} className="mb-3">
                  <div className="mb-3">
                    <label className="form-label">
                      <i className="fas fa-building me-1"></i>
                      Cari Vendor
                    </label>
                    <div className="input-group">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="Contoh: Adhi Karya"
                        value={quickSearch.vendor}
                        onChange={(e) => setQuickSearch(prev => ({ ...prev, vendor: e.target.value }))}
                      />
                      <button
                        className="btn btn-primary"
                        onClick={() => handleQuickSearch('vendor')}
                      >
                        <i className="fas fa-search"></i>
                      </button>
                    </div>
                    <div className="mt-2 d-flex justify-content-between">
                      <small className="text-muted">Cari perusahaan/penyedia</small>
                      <Button 
                        variant="link" 
                        size="sm"
                        onClick={() => handleDemoSearch('vendor')}
                      >
                        <i className="fas fa-magic me-1"></i>
                        Demo
                      </Button>
                    </div>
                  </div>
                </Col>
                
                <Col md={6} className="mb-3">
                  <div className="mb-3">
                    <label className="form-label">
                      <i className="fas fa-box me-1"></i>
                      Cari Paket
                    </label>
                    <div className="input-group">
                      <input
                        type="text"
                        className="form-control"
                        placeholder="Contoh: jalan, bangunan"
                        value={quickSearch.package}
                        onChange={(e) => setQuickSearch(prev => ({ ...prev, package: e.target.value }))}
                      />
                      <button
                        className="btn btn-success"
                        onClick={() => handleQuickSearch('package')}
                      >
                        <i className="fas fa-search"></i>
                      </button>
                    </div>
                    <div className="mt-2 d-flex justify-content-between">
                      <small className="text-muted">Cari tender/paket pengadaan</small>
                      <Button 
                        variant="link" 
                        size="sm"
                        onClick={() => handleDemoSearch('package')}
                      >
                        <i className="fas fa-magic me-1"></i>
                        Demo
                      </Button>
                    </div>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Features */}
      <Row className="mb-5">
        <Col>
          <h4 className="mb-4 text-center">
            <i className="fas fa-star me-2 text-warning"></i>
            Fitur Unggulan
          </h4>
          
          <Row>
            {[
              {
                title: 'Pencarian Vendor',
                desc: 'Cari rekanan berdasarkan nama perusahaan',
                icon: 'fas fa-building',
                color: 'primary',
                path: '/vendor'
              },
              {
                title: 'Pencarian Paket',
                desc: 'Cari tender berdasarkan kata kunci',
                icon: 'fas fa-box',
                color: 'success',
                path: '/package'
              },
              {
                title: 'SBU LPJK',
                desc: 'Cari sertifikat badan usaha',
                icon: 'fas fa-certificate',
                color: 'info',
                path: '/sbu'
              },
              {
                title: 'Daftar LPSE',
                desc: 'Akses semua LPSE Indonesia',
                icon: 'fas fa-list',
                color: 'warning',
                path: '/lpse'
              }
            ].map((feature, index) => (
              <Col key={index} md={3} className="mb-4">
                <Card 
                  className="shadow-sm h-100 border-0 text-center hover-shadow"
                  onClick={() => navigate(feature.path)}
                  style={{ cursor: 'pointer' }}
                >
                  <Card.Body className="py-4">
                    <div className={`icon-wrapper bg-${feature.color} bg-opacity-10 rounded-circle d-inline-flex align-items-center justify-content-center mb-3`} 
                         style={{ width: '70px', height: '70px' }}>
                      <i className={`${feature.icon} fa-2x text-${feature.color}`}></i>
                    </div>
                    <h5 className="card-title">{feature.title}</h5>
                    <p className="card-text text-muted small">{feature.desc}</p>
                    <Button variant={`outline-${feature.color}`} size="sm">
                      Akses <i className="fas fa-arrow-right ms-1"></i>
                    </Button>
                  </Card.Body>
                </Card>
              </Col>
            ))}
          </Row>
        </Col>
      </Row>

      {/* Info */}
      <Row>
        <Col>
          <Alert variant="info" className="text-center">
            <h5>
              <i className="fas fa-info-circle me-2"></i>
              Informasi Aplikasi
            </h5>
            <p className="mb-0">
              Support tahun 2023-2026 • Sistem autentikasi • Export data CSV • Multi-LPSE search
            </p>
            <div className="mt-3">
              <Link to="/auth" className="btn btn-outline-primary me-2">
                <i className="fas fa-user me-1"></i>
                Login/Register
              </Link>
              <Button 
                variant="outline-secondary"
                onClick={() => window.open('http://localhost:5000/health', '_blank')}
              >
                <i className="fas fa-server me-1"></i>
                Cek Backend
              </Button>
            </div>
          </Alert>
        </Col>
      </Row>
    </Container>
  );
};

export default HomePage;